:"ef1658b2eb58a376f368ede88730ad43"}},{"signature":"nothingsports_read_current_fixture_bundle_json(text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"a91f9bc32b11190240bba20ff0870bd8"}},{"signature":"nothingsports_read_current_fixture_bundle_json_rows(text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"6e6a06e0ca5a3206a138cb88a400e84b"}},{"signature":"nothingsports_read_current_fixtures(text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"8f7e452c8a96f15ed11b50b4ea5cb751"}},{"signature":"nothingsports_read_participant_fixture_bundle(text[],text[],text[],text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"df1f9773b0f210c122f6c55fe8425f3c"}},{"signature":"public.nothingsports_read_match_centre_fixture_bundle(text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"09c1fb11e09a04dfa5c58350d7153e39"}},{"signature":"nothingsports_fixture_read_private.near_fields(jsonb,jsonb,jsonb,jsonb,timestamp with time zone)","contract":{"acl":"{postgres=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"83828d2b5f42d80bf99d0ef5422064ca"}},{"signature":"nothingsports_fixture_read_private.rebuild_near_selection(text,text)","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":true,"parallel":"u","volatile":"v","leakproof":false,"definition":"f5201e809cbc9ef24fe8a6bdbe013340"}},{"signature":"nothingsports_fixture_read_private.near_index_ready()","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"98503336cb97173edfcf1129fd14673a"}},{"signature":"nothingsports_fixture_read_private.read_near_raw(text[])","contract":{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"owner":"postgres","config":["search_path=\"\""],"strict":false,"definer":false,"parallel":"u","volatile":"s","leakproof":false,"definition":"24bf763bb95dc6fdff000e9ee42efc10"}}]$functions$::jsonb;
 expected_table constant jsonb := $table_contract${"acl":"{postgres=arwdDxtm/postgres,service_role=r/postgres}","rls":true,"owner":"postgres","forced":true,"columns":[[1,"source_id","text",true,"",false,null],[2,"fixture_id","text",true,"",false,null],[3,"shape_version","smallint",true,"",false,null],[4,"status","text",false,"",false,null],[5,"start_kind","smallint",true,"",false,null],[6,"start_at","timestamp with time zone",false,"",false,null],[7,"completion_at","timestamp with time zone",false,"",false,null],[8,"completion_unqualified","boolean",true,"",false,null],[9,"lookup_uncertain","boolean",true,"",false,null]],"indexes":["CREATE INDEX near_selection_completion_idx ON nothingsports_fixture_read_private.near_selection USING btree (status, completion_at, source_id, fixture_id) WHERE (completion_at IS NOT NULL)","CREATE INDEX near_selection_exception_idx ON nothingsports_fixture_read_private.near_selection USING btree (source_id, fixture_id) INCLUDE (shape_version, status, start_kind, completion_unqualified, lookup_uncertain) WHERE ((shape_version <> 1) OR (start_kind = 2) OR completion_unqualified OR lookup_uncertain)","CREATE UNIQUE INDEX near_selection_pkey ON nothingsports_fixture_read_private.near_selection USING btree (source_id, fixture_id)","CREATE INDEX near_selection_start_idx ON nothingsports_fixture_read_private.near_selection USING btree (status, start_at, source_id, fixture_id)"],"constraints":[["near_selection_check","CHECK (((start_kind = 1) = (start_at IS NOT NULL)))"],["near_selection_pkey","PRIMARY KEY (source_id, fixture_id)"],["near_selection_shape_version_check","CHECK ((shape_version = ANY (ARRAY[0, 1])))"],["near_selection_source_id_fixture_id_fkey","FOREIGN KEY (source_id, fixture_id) REFERENCES nothingsports_fixture_current(source_id, fixture_id) ON UPDATE CASCADE ON DELETE CASCADE"],["near_selection_start_kind_check","CHECK ((start_kind = ANY (ARRAY[0, 1, 2])))"]],"policies":0,"schema":{"owner":"postgres","acl":"{postgres=UC/postgres,service_role=U/postgres}"}}$table_contract$::jsonb;
 table_query constant text := $table_query$select jsonb_build_object('acl',c.relacl::text,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,'columns',(select jsonb_agg(jsonb_build_array(a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attgenerated::text,a.atthasdef,a.attacl::text)order by a.attnum)from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(jsonb_build_array(conname,pg_get_constraintdef(oid))order by conname)from pg_constraint where conrelid=c.oid and contype<>'n'),'indexes',(select jsonb_agg(pg_get_indexdef(indexrelid)order by indexrelid::regclass::text)from pg_index where indrelid=c.oid),'policies',(select count(*)from pg_policy where polrelid=c.oid),'schema',(select jsonb_build_object('owner',pg_get_userbyid(n.nspowner),'acl',n.nspacl::text)from pg_namespace n where n.oid=c.relnamespace)) contract from pg_class c where c.oid='nothingsports_fixture_read_private.near_selection'::regclass$table_query$;
 wanted jsonb; actual_function jsonb; actual_table jsonb;
 before_definition text; after_definition text; round_trip text;
 from_head constant text := $from_head$  from candidates selected
  left join receipts r on r.source_id=selected.source_id and r.fixture_id=selected.fixture_id
  cross join lateral (
$from_head$;
 to_head constant text := $to_head$  from candidates selected
  cross join lateral (
$to_head$;
 from_tail constant text := $from_tail$  ) c
 )
 select jsonb_build_object$from_tail$;
 to_tail constant text := $to_tail$  ) c
  left join receipts r on r.source_id=c.source_id and r.fixture_id=c.fixture_id
 )
 select jsonb_build_object$to_tail$;
BEGIN
  FOR wanted IN SELECT value FROM jsonb_array_elements(expected_functions) LOOP
   SELECT jsonb_build_object('definition',md5(pg_get_functiondef(p.oid)),'acl',p.proacl::text,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'volatile',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict,'cost',p.procost,'leakproof',p.proleakproof,'config',p.proconfig) INTO actual_function FROM pg_proc p WHERE p.oid=to_regprocedure(wanted->>'signature');
   IF actual_function IS DISTINCT FROM wanted->'contract' THEN RAISE EXCEPTION 'Near receipt input function contract differs: %',wanted->>'signature'; END IF;
  END LOOP;
  EXECUTE table_query INTO actual_table;
  IF actual_table IS DISTINCT FROM expected_table THEN RAISE EXCEPTION 'Near receipt input private table contract differs'; END IF;
  SELECT pg_get_functiondef(target) INTO before_definition;
  IF md5((SELECT prosrc FROM pg_proc WHERE oid=target)) <> '402458f178989eed547f96e2ce2995c1' THEN RAISE EXCEPTION 'Near receipt body preimage differs'; END IF;
  IF (length(before_definition)-length(replace(before_definition,from_head,'')))/length(from_head) <> 1
   OR (length(before_definition)-length(replace(before_definition,from_tail,'')))/length(from_tail) <> 1 THEN
   RAISE EXCEPTION 'Near receipt exact rewrite boundary differs';
  END IF;
  after_definition := replace(replace(before_definition,from_head,to_head),from_tail,to_tail);
  round_trip := replace(replace(after_definition,to_head,from_head),to_tail,from_tail);
  IF round_trip IS DISTINCT FROM before_definition OR md5(after_definition) <> 'efc32656d8c100d80543001a2c5e6b48' THEN
   RAISE EXCEPTION 'Near receipt exact definition round trip differs';
  END IF;
  EXECUTE after_definition;
  IF pg_get_functiondef(target) IS DISTINCT FROM after_definition OR md5((SELECT prosrc FROM pg_proc WHERE oid=target)) <> '3e1d234315b0eae31e2fc4ec491de3dd' THEN
   RAISE EXCEPTION 'Near receipt canonical output differs';
  END IF;
  expected_functions := jsonb_set(expected_functions,'{22,contract,definition}',to_jsonb('efc32656d8c100d80543001a2c5e6b48'::text));
  FOR wanted IN SELECT value FROM jsonb_array_elements(expected_functions) LOOP
   SELECT jsonb_build_object('definition',md5(pg_get_functiondef(p.oid)),'acl',p.proacl::text,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'volatile',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict,'cost',p.procost,'leakproof',p.proleakproof,'config',p.proconfig) INTO actual_function FROM pg_proc p WHERE p.oid=to_regprocedure(wanted->>'signature');
   IF actual_function IS DISTINCT FROM wanted->'contract' THEN RAISE EXCEPTION 'Near receipt output function contract differs: %',wanted->>'signature'; END IF;
  END LOOP;
  EXECUTE table_query INTO actual_table;
  IF actual_table IS DISTINCT FROM expected_table THEN RAISE EXCEPTION 'Near receipt output private table contract differs'; END IF;
END
$receipt_join$;
COMMIT;
